import React, { useState, useEffect } from 'react';
import * as bip39 from 'bip39';
import { Connection, Keypair, PublicKey, Transaction, LAMPORTS_PER_SOL, SystemProgram } from '@solana/web3.js';
import { getAccount, getAssociatedTokenAddress, getMint, createAssociatedTokenAccountInstruction, createTransferInstruction } from '@solana/spl-token';
import { derivePath } from 'ed25519-hd-key';
import { Buffer } from 'buffer';
import { Transak } from '@transak/transak-sdk';
import { QRCodeCanvas } from 'qrcode.react';
import './App.css';
import logo from './logo.png';

window.Buffer = window.Buffer || Buffer;

function App() {
  const [solanaAddress, setSolanaAddress] = useState('');
  const [memeTorrentAddress, setMemeTorrentAddress] = useState('');
  const [mnemonic, setMnemonic] = useState('');
  const [balance, setBalance] = useState('');
  const [solBalance, setSolBalance] = useState('');
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');
  const [mnemonicInput, setMnemonicInput] = useState('');
  const [showMnemonicInput, setShowMnemonicInput] = useState(false);
  const [showMnemonic, setShowMnemonic] = useState(false);
  const [buyAmount, setBuyAmount] = useState('');
  const [recipientAddress, setRecipientAddress] = useState('');
  const [sendAmount, setSendAmount] = useState('');
  const [sendType, setSendType] = useState('MT');
  const [keypair, setKeypair] = useState(null);
  const [copied, setCopied] = useState(false);
  const [activeTab, setActiveTab] = useState('wallet');
  const [loading, setLoading] = useState(false);

  const connection = new Connection(process.env.REACT_APP_QUICKNODE_RPC_URL, 'confirmed');
  const MT_MINT_ADDRESS = process.env.REACT_APP_MT_MINT_ADDRESS || 'ELywDcVX2WumHm4xEfqF8NdEKaeGCAaq9JmwtjE8pump';

  const wordCount = mnemonicInput.trim().split(/\s+/).filter(word => word.length > 0).length;

  useEffect(() => {
    if (success) {
      const timer = setTimeout(() => setSuccess(''), 5000);
      return () => clearTimeout(timer);
    }
  }, [success]);

  useEffect(() => {
    if (solanaAddress) {
      checkBalance();
    }
  }, [solanaAddress]);

  const deriveWallet = async (mnemonic) => {
    const normalizedMnemonic = mnemonic.trim().toLowerCase().replace(/\s+/g, ' ');
    console.log('Normalized mnemonic (masked):', normalizedMnemonic.split(' ').slice(0, 2).join(' ') + ' ***** ' + normalizedMnemonic.split(' ').slice(-2).join(' '));
    const seed = await bip39.mnemonicToSeed(normalizedMnemonic);
    const path = `m/44'/501'/0'`; // Hardcoded to match Phantom's common path
    console.log('Deriving key with path:', path);
    const derivedSeed = derivePath(path, seed).key;
    const keypair = Keypair.fromSeed(derivedSeed);
    console.log('Derived public key:', keypair.publicKey.toBase58());
    return keypair;
  };

  const createWallet = async () => {
    setLoading(true);
    try {
      const mnemonicPhrase = bip39.generateMnemonic();
      const solanaKeypair = await deriveWallet(mnemonicPhrase);
      const memeTorrentPlaceholder = 'MEMETORRENT_ADDRESS_' + solanaKeypair.publicKey.toBase58();
      setMnemonic(mnemonicPhrase);
      setSolanaAddress(solanaKeypair.publicKey.toBase58());
      setMemeTorrentAddress(memeTorrentPlaceholder);
      setKeypair(solanaKeypair);
      setError('');
      setSuccess('Wallet created successfully! Save your mnemonic securely.');
      setShowMnemonic(true);
      localStorage.setItem('mnemonic', mnemonicPhrase);
    } catch (err) {
      setError('Failed to create wallet: ' + err.message);
      console.error('Create wallet error:', err);
    } finally {
      setLoading(false);
    }
  };

  const loadWallet = async () => {
    setLoading(true);
    try {
      const storedMnemonic = localStorage.getItem('mnemonic');
      if (!storedMnemonic) {
        setError('No wallet found in storage. Try recovering with your mnemonic in Settings.');
        return;
      }
      if (!bip39.validateMnemonic(storedMnemonic)) {
        setError('Invalid mnemonic in storage. Try recovering with your mnemonic directly in Settings.');
        return;
      }
      const solanaKeypair = await deriveWallet(storedMnemonic);
      const memeTorrentPlaceholder = 'MEMETORRENT_ADDRESS_' + solanaKeypair.publicKey.toBase58();
      setMnemonic(storedMnemonic);
      setSolanaAddress(solanaKeypair.publicKey.toBase58());
      setMemeTorrentAddress(memeTorrentPlaceholder);
      setKeypair(solanaKeypair);
      setError('');
      setSuccess('Wallet loaded successfully!');
      setShowMnemonic(false);
    } catch (err) {
      setError('Failed to load wallet: ' + err.message);
      console.error('Load wallet error:', err);
    } finally {
      setLoading(false);
    }
  };

  const loadWalletFromMnemonic = async () => {
    setLoading(true);
    try {
      if (!mnemonicInput) {
        setError('Please enter a mnemonic phrase');
        return;
      }
      if (!bip39.validateMnemonic(mnemonicInput)) {
        setError('Invalid mnemonic phrase. Ensure it is 12, 15, 18, 21, or 24 words from the BIP-39 wordlist.');
        return;
      }
      const solanaKeypair = await deriveWallet(mnemonicInput);
      const memeTorrentPlaceholder = 'MEMETORRENT_ADDRESS_' + solanaKeypair.publicKey.toBase58();
      setMnemonic(mnemonicInput);
      setSolanaAddress(solanaKeypair.publicKey.toBase58());
      setMemeTorrentAddress(memeTorrentPlaceholder);
      setKeypair(solanaKeypair);
      setError('');
      setSuccess('Wallet recovered successfully!');
      setShowMnemonic(false);
      setMnemonicInput('');
      setShowMnemonicInput(false);
      setActiveTab('wallet');
      localStorage.setItem('mnemonic', mnemonicInput);
    } catch (err) {
      setError('Failed to load wallet from mnemonic: ' + err.message);
      console.error('Load wallet from mnemonic error:', err);
    } finally {
      setLoading(false);
    }
  };

  const checkBalance = async () => {
    setLoading(true);
    try {
      if (!solanaAddress) {
        setError('Solana address is not set. Please load or recover a wallet.');
        return;
      }
      const owner = new PublicKey(solanaAddress);
      const tokenMint = new PublicKey(MT_MINT_ADDRESS);
      const tokenAccount = await getAssociatedTokenAddress(tokenMint, owner, false);
      try {
        const accountInfo = await getAccount(connection, tokenAccount);
        const mintInfo = await getMint(connection, tokenMint);
        const decimals = mintInfo.decimals;
        const formattedBalance = (Number(accountInfo.amount) / Math.pow(10, decimals)).toFixed(decimals);
        setBalance(formattedBalance);
      } catch (err) {
        setBalance('0');
      }
      const solBal = await connection.getBalance(owner);
      setSolBalance((solBal / LAMPORTS_PER_SOL).toFixed(6));
      setError('');
    } catch (err) {
      setError('Failed to fetch balances: ' + err.message);
      console.error('Balance check error:', err);
    } finally {
      setLoading(false);
    }
  };

  const buyMtWithFiat = async () => {
    setLoading(true);
    try {
      if (!buyAmount || parseFloat(buyAmount) <= 0) {
        setError('Please specify a valid amount to buy.');
        return;
      }
      if (!solanaAddress) {
        setError('Wallet address not set.');
        return;
      }
      if (!process.env.REACT_APP_TRANSAK_API_KEY) {
        setError('Transak API key is missing.');
        return;
      }
      const transakConfig = {
        apiKey: process.env.REACT_APP_TRANSAK_API_KEY,
        environment: 'PRODUCTION',
        defaultCryptoCurrency: 'SOL',
        walletAddress: solanaAddress,
        fiatCurrency: 'USD',
        fiatAmount: parseFloat(buyAmount),
        network: 'solana',
      };
      console.log('Initializing Transak with config:', transakConfig);
      const transak = new Transak(transakConfig);
      console.log('Transak instance created:', transak);
      if (typeof transak.on !== 'function') {
        throw new Error('transak.on is not a function. Check Transak SDK initialization.');
      }
      transak.on('ORDER_COMPLETED', (data) => {
        console.log('Transak ORDER_COMPLETED:', data);
        setError('');
        setSuccess('Purchase successful! Tokens should arrive shortly.');
        checkBalance();
        transak.close();
      });
      transak.on('ORDER_FAILED', (data) => {
        console.log('Transak ORDER_FAILED:', data);
        setError('Purchase failed: ' + (data?.errorMessage || 'Unknown error'));
        transak.close();
      });
      transak.on('*', (event) => {
        console.log('Transak event:', event);
      });
      transak.init();
    } catch (err) {
      setError('Failed to initiate purchase: ' + err.message);
      console.error('Buy error:', err);
    } finally {
      setLoading(false);
    }
  };

  const sellMtWithFiat = async () => {
    setLoading(true);
    try {
      if (!buyAmount || parseFloat(buyAmount) <= 0) {
        setError('Please specify a valid amount to sell.');
        return;
      }
      if (!solanaAddress) {
        setError('Wallet address not set.');
        return;
      }
      if (!process.env.REACT_APP_TRANSAK_API_KEY) {
        setError('Transak API key is missing.');
        return;
      }
      const transakConfig = {
        apiKey: process.env.REACT_APP_TRANSAK_API_KEY,
        environment: 'PRODUCTION',
        defaultCryptoCurrency: 'SOL',
        walletAddress: solanaAddress,
        cryptoAmount: parseFloat(buyAmount),
        network: 'solana',
        isBuyOrSell: 'SELL',
      };
      console.log('Initializing Transak with config:', transakConfig);
      const transak = new Transak(transakConfig);
      console.log('Transak instance created:', transak);
      if (typeof transak.on !== 'function') {
        throw new Error('transak.on is not a function. Check Transak SDK initialization.');
      }
      transak.on('ORDER_COMPLETED', (data) => {
        console.log('Transak ORDER_COMPLETED:', data);
        setError('');
        setSuccess('Sale successful! Check your fiat account.');
        checkBalance();
        transak.close();
      });
      transak.on('ORDER_FAILED', (data) => {
        console.log('Transak ORDER_FAILED:', data);
        setError('Sale failed: ' + (data?.errorMessage || 'Unknown error'));
        transak.close();
      });
      transak.on('*', (event) => {
        console.log('Transak event:', event);
      });
      transak.init();
    } catch (err) {
      setError('Failed to initiate sale: ' + err.message);
      console.error('Sell error:', err);
    } finally {
      setLoading(false);
    }
  };

  const sendMt = async () => {
    setLoading(true);
    try {
      if (!keypair || !recipientAddress || !sendAmount || parseFloat(sendAmount) <= 0) {
        setError('Wallet, recipient address, or valid amount missing.');
        return;
      }
      const senderPublicKey = keypair.publicKey;
      const recipientPublicKey = new PublicKey(recipientAddress);
      const mintPublicKey = new PublicKey(MT_MINT_ADDRESS);
      const senderTokenAccount = await getAssociatedTokenAddress(mintPublicKey, senderPublicKey, false);
      const recipientTokenAccount = await getAssociatedTokenAddress(mintPublicKey, recipientPublicKey, false);
      const mintInfo = await getMint(connection, mintPublicKey);
      const amount = parseFloat(sendAmount) * Math.pow(10, mintInfo.decimals);
      const solBalance = await connection.getBalance(senderPublicKey);
      if (solBalance < 0.005 * LAMPORTS_PER_SOL) {
        setError('Insufficient SOL for fees (~0.005 SOL needed).');
        return;
      }
      let senderAccountInfo;
      try {
        senderAccountInfo = await getAccount(connection, senderTokenAccount);
        const senderBalance = Number(senderAccountInfo.amount) / Math.pow(10, mintInfo.decimals);
        if (senderBalance < parseFloat(sendAmount)) {
          setError(`Insufficient $MT balance. Available: ${senderBalance}, Required: ${sendAmount}`);
          return;
        }
      } catch (err) {
        setError('Sender $MT token account does not exist.');
        return;
      }
      const transaction = new Transaction();
      try {
        await getAccount(connection, recipientTokenAccount);
      } catch (err) {
        transaction.add(
          createAssociatedTokenAccountInstruction(
            senderPublicKey,
            recipientTokenAccount,
            recipientPublicKey,
            mintPublicKey
          )
        );
      }
      transaction.add(
        createTransferInstruction(
          senderTokenAccount,
          recipientTokenAccount,
          senderPublicKey,
          amount
        )
      );
      const { blockhash, lastValidBlockHeight } = await connection.getLatestBlockhash('confirmed');
      transaction.recentBlockhash = blockhash;
      transaction.feePayer = senderPublicKey;
      const signature = await connection.sendTransaction(transaction, [keypair], {
        skipPreflight: false,
        preflightCommitment: 'confirmed',
        maxRetries: 5,
      });
      await connection.confirmTransaction(
        { signature, blockhash, lastValidBlockHeight },
        'confirmed'
      );
      setError('');
      setSuccess('MT sent successfully! TxID: ' + signature);
      await checkBalance();
    } catch (err) {
      setError('Failed to send $MT: ' + err.message);
      console.error('Send MT error:', err);
    } finally {
      setLoading(false);
    }
  };

  const sendSol = async () => {
    setLoading(true);
    try {
      if (!keypair || !recipientAddress || !sendAmount || parseFloat(sendAmount) <= 0) {
        setError('Wallet, recipient address, or valid amount missing.');
        return;
      }
      const senderPublicKey = keypair.publicKey;
      const recipientPublicKey = new PublicKey(recipientAddress);
      const solBalance = await connection.getBalance(senderPublicKey);
      const amount = parseFloat(sendAmount) * LAMPORTS_PER_SOL;
      if (solBalance < amount + 0.005 * LAMPORTS_PER_SOL) {
        setError('Insufficient SOL for transaction and fees (~0.005 SOL needed).');
        return;
      }
      const transaction = new Transaction().add(
        SystemProgram.transfer({
          fromPubkey: senderPublicKey,
          toPubkey: recipientPublicKey,
          lamports: amount,
        })
      );
      const { blockhash, lastValidBlockHeight } = await connection.getLatestBlockhash('confirmed');
      transaction.recentBlockhash = blockhash;
      transaction.feePayer = senderPublicKey;
      const signature = await connection.sendTransaction(transaction, [keypair], {
        skipPreflight: false,
        preflightCommitment: 'confirmed',
        maxRetries: 5,
      });
      await connection.confirmTransaction(
        { signature, blockhash, lastValidBlockHeight },
        'confirmed'
      );
      setError('');
      setSuccess('SOL sent successfully! TxID: ' + signature);
      await checkBalance();
    } catch (err) {
      setError('Failed to send SOL: ' + err.message);
      console.error('Send SOL error:', err);
    } finally {
      setLoading(false);
    }
  };

  const copyAddress = () => {
    if (solanaAddress) {
      navigator.clipboard.writeText(solanaAddress);
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    }
  };

  return (
    <div className="App">
      <h2>Futuret3ch | MemeTorrent</h2>
      <img src={logo} alt="Infinite Wallet Logo" className="logo" />
      <p>Masters of Innovation</p>
      {loading && <p className="loading">Loading...</p>}
      <div className="tab-container">
        <div className="tab-buttons">
          <button className={activeTab === 'wallet' ? 'active' : ''} onClick={() => setActiveTab('wallet')}>
            Wallet
          </button>
          <button className={activeTab === 'buy-sell' ? 'active' : ''} onClick={() => setActiveTab('buy-sell')}>
            Buy/Sell
          </button>
          <button className={activeTab === 'send-receive' ? 'active' : ''} onClick={() => setActiveTab('send-receive')}>
            Send/Receive
          </button>
          <button className={activeTab === 'settings' ? 'active' : ''} onClick={() => setActiveTab('settings')}>
            Settings
          </button>
        </div>
        <div className="tab-content">
          {activeTab === 'wallet' && (
            <div className="wallet-tab">
              <h3>Wallet</h3>
              <div className="button-group">
                <button onClick={createWallet} disabled={loading}>Create Wallet</button>
                <button onClick={loadWallet} disabled={loading}>Load Wallet</button>
                <button className="check-balance" onClick={checkBalance} disabled={loading}>
                  Check Balances
                </button>
              </div>
              {solanaAddress && (
                <div className="wallet-info">
                  <p><strong>Solana Address:</strong> {solanaAddress}</p>
                  <p><strong>MemeTorrent Address (Placeholder):</strong> {memeTorrentAddress}</p>
                  <p><strong>$MT Balance:</strong> {balance || '0'}</p>
                  <p><strong>SOL Balance:</strong> {solBalance || '0'} SOL</p>
                </div>
              )}
              {mnemonic && (
                <p>
                  <strong>Mnemonic (Save securely!):</strong>{' '}
                  {showMnemonic ? mnemonic : '************'}
                  <button className="show-mnemonic-btn" onClick={() => setShowMnemonic(!showMnemonic)}>
                    {showMnemonic ? 'Hide' : 'Show'} Mnemonic
                  </button>
                </p>
              )}
            </div>
          )}
          {activeTab === 'buy-sell' && (
            <div className="buy-sell-tab">
              <h3>Buy/Sell $MT with Fiat</h3>
              <input
                type="number"
                placeholder="Amount to buy/sell (USD for buy, $MT for sell)"
                value={buyAmount}
                onChange={(e) => setBuyAmount(e.target.value)}
                min="0"
                step="0.01"
                disabled={loading}
              />
              <div className="button-group">
                <button onClick={buyMtWithFiat} disabled={!solanaAddress || !buyAmount || parseFloat(buyAmount) <= 0 || loading}>
                  Buy $MT with Fiat
                </button>
                <button onClick={sellMtWithFiat} disabled={!solanaAddress || !buyAmount || parseFloat(buyAmount) <= 0 || loading}>
                  Sell $MT for Fiat
                </button>
              </div>
              <div className="swap-section">
                <h3>Swap SOL/$MT</h3>
                <p>Swaps are disabled. Use <a href="https://raydium.io/swap/" target="_blank" rel="noopener noreferrer">Raydium</a>.</p>
              </div>
            </div>
          )}
          {activeTab === 'send-receive' && (
            <div className="send-receive-tab">
              <h3>Send/Receive $MT or SOL</h3>
              <div className="send-section">
                <h4>Send $MT or SOL</h4>
                <select value={sendType} onChange={(e) => setSendType(e.target.value)} disabled={loading}>
                  <option value="MT">$MT</option>
                  <option value="SOL">SOL</option>
                </select>
                <input
                  type="text"
                  placeholder="Recipient Address"
                  value={recipientAddress}
                  onChange={(e) => setRecipientAddress(e.target.value)}
                  disabled={loading}
                />
                <input
                  type="number"
                  placeholder={`Amount to send (${sendType})`}
                  value={sendAmount}
                  onChange={(e) => setSendAmount(e.target.value)}
                  min="0"
                  step="0.01"
                  disabled={loading}
                />
                <button
                  onClick={sendType === 'MT' ? sendMt : sendSol}
                  disabled={!solanaAddress || !recipientAddress || !sendAmount || parseFloat(sendAmount) <= 0 || loading}
                >
                  Send {sendType}
                </button>
              </div>
              <div className="receive-section">
                <h4>Receive $MT or SOL</h4>
                <p><strong>Your Solana Address:</strong> {solanaAddress || 'No wallet loaded'}</p>
                {solanaAddress && (
                  <>
                    <button onClick={copyAddress} disabled={loading}>
                      {copied ? 'Copied!' : 'Copy Address'}
                    </button>
                    <div className="qr-code">
                      <QRCodeCanvas value={solanaAddress} size={128} />
                    </div>
                  </>
                )}
                <p><strong>$MT Balance:</strong> {balance || '0'}</p>
                <p><strong>SOL Balance:</strong> {solBalance || '0'} SOL</p>
              </div>
            </div>
          )}
          {activeTab === 'settings' && (
            <div className="settings-tab">
              <h3>Settings</h3>
              <div className="mnemonic-toggle">
                <button onClick={() => setShowMnemonicInput(!showMnemonicInput)} disabled={loading}>
                  {showMnemonicInput ? 'Hide Mnemonic Input' : 'Recover Wallet with Mnemonic'}
                </button>
                {showMnemonicInput && (
                  <div className="mnemonic-input">
                    <input
                      type="text"
                      placeholder="Enter your 12-word mnemonic phrase"
                      value={mnemonicInput}
                      onChange={(e) => setMnemonicInput(e.target.value)}
                      disabled={loading}
                    />
                    <p className="word-count">Words entered: {wordCount}</p>
                    <button onClick={loadWalletFromMnemonic} disabled={loading}>
                      Load from Mnemonic
                    </button>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      </div>
      {error && <p className="error">{error}</p>}
      {success && <p className="success">{success}</p>}
    </div>
  );
}

export default App;